package br.com.onda;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class ImageCatalogTest {
 private JSONObject page(String name,int index,String mime,String media,String license)throws Exception{return new JSONObject().put("title","File:"+name).put("index",index).put("imageinfo",new JSONArray().put(new JSONObject().put("mime",mime).put("thumburl",media).put("descriptionurl","https://commons.wikimedia.org/wiki/File:"+name).put("extmetadata",new JSONObject().put("Artist",new JSONObject().put("value","<a href='x'>Autora &amp; artista</a>")).put("LicenseShortName",new JSONObject().put("value",license)))));}
 @Test public void photosKeepRankingAttributionAndDistinctSources()throws Exception{JSONArray pages=new JSONArray().put(page("B.jpg",2,"image/jpeg","https://upload.wikimedia.org/b.jpg","CC BY-SA 4.0")).put(page("A.png",1,"image/png","https://upload.wikimedia.org/a.png","CC0")).put(page("A.png",3,"image/png","https://upload.wikimedia.org/a.png","CC0"));List<ImageCatalog.Photo> out=ImageCatalog.parse(new JSONObject().put("query",new JSONObject().put("pages",pages)).toString());assertEquals(2,out.size());assertEquals("A.png",out.get(0).title);assertEquals("Autora & artista",out.get(0).credit);assertTrue(out.get(0).attribution().contains("CC0"));}
 @Test public void skipsUnsafeMimeHostAndMissingLicense()throws Exception{JSONArray a=new JSONArray().put(page("bad.svg",1,"image/svg+xml","https://upload.wikimedia.org/a.svg","CC0")).put(page("bad.png",2,"image/png","https://evil.org/a.png","CC0")).put(page("none.jpg",3,"image/jpeg","https://upload.wikimedia.org/a.jpg",""));assertTrue(ImageCatalog.parse(new JSONObject().put("query",new JSONObject().put("pages",a)).toString()).isEmpty());}
 @Test public void exactHttpsHostsOnly(){for(String url:new String[]{"http://upload.wikimedia.org/a.png","https://upload.wikimedia.org.evil.org/a.png","https://user@upload.wikimedia.org/a.png","file:///a.png","https://upload.wikimedia.org:8080/a.png"})try{ImageCatalog.mediaUrl(url);fail(url);}catch(IllegalArgumentException expected){}assertEquals("https://upload.wikimedia.org/a%20b.jpg",ImageCatalog.mediaUrl("https://upload.wikimedia.org/a%20b.jpg"));}
 @Test public void emptyResultsAndQueryEncoding()throws Exception{assertTrue(ImageCatalog.parse("{\"batchcomplete\":true}").isEmpty());String url=ImageCatalog.endpoint("céu & flores",20);assertTrue(url.contains("gsroffset=20"));assertTrue(url.contains("c%C3%A9u+%26+flores"));try{ImageCatalog.parse("{\"error\":{}}");fail();}catch(JSONException expected){}}
}
